window.__esigi = (nome, ok, misure) => { if (!ok) throw new Error(nome + ' — ' + JSON.stringify(misure)); return misure };
window.__mobilia = () => { const plancia=document.querySelector('.plancia').getBoundingClientRect(); const banco=document.querySelector('.banco').getBoundingClientRect(); return document.body.dataset.appeso === 'si' && document.body.dataset.dump !== 'aperto' ? Math.max(plancia.bottom, banco.bottom) : plancia.bottom };
window.__bancoOpaco = () => { const banco=document.querySelector('.banco'); const rb=banco.getBoundingClientRect(); const rp=document.querySelector('.plancia').getBoundingClientRect(); const cima=Math.max(rb.top, rp.bottom); const fondo=Math.min(rb.bottom, window.innerHeight); let punti=0, intrusi=0, primo=null; for (let y=Math.ceil(cima)+1; y<fondo-1; y+=16) { for (let x=Math.ceil(rb.left)+1; x<rb.right-1; x+=16) { punti++; const e=document.elementFromPoint(x,y); if (!e || !(e===banco || banco.contains(e))) { intrusi++; if (!primo) primo={x,y,chi:e?e.className:null} } } } return { punti, intrusi, primo } };
window.__fuoco = async (comandi) => { let peggio=null; for (const b of comandi) { b.focus(); await new Promise(r=>setTimeout(r,120)); const r=b.getBoundingClientRect(); const m=window.__mobilia(); const sotto=Math.round((r.top-m)*10)/10; const centro=document.elementFromPoint(Math.round(r.left+r.width/2), Math.round(r.top+r.height/2)); const suo=centro===b||b.contains(centro); if (!peggio || sotto<peggio.sotto) peggio={ testo:b.textContent.trim().slice(0,32), top:Math.round(r.top*10)/10, mobilia:Math.round(m*10)/10, sotto, ilPuntoCentraleE:centro?centro.className:null, riceveIlClick:suo }; } return peggio };
return { pannelli: document.querySelectorAll('.pila [data-pannello]').length, dump: document.body.dataset.dump }
